  if (stage <= nstages) {
    if (stage_wghts[stage-1].main_stage) {
      if (integrator != "rk2") ATHENA_ERROR("x3i_ct requires SSPRK2");
      X3ICTBeginStage(pmb, stage, pmb->pmy_mesh->time + (stage == 2 ? pmb->pmy_mesh->dt : 0), pmb->pmy_mesh->dt);
